def confirmAuth(headers):
    auth_token_header = headers.get('Authorization')
    if not auth_token_header or not auth_token_header.startswith('Basic '):
        raise ValueError("Invalid Authorization header")

    encoded_token = auth_token_header.split(' ')[1]
    try:
        decoded_token = base64.b64decode(encoded_token)
    except Exception as e:
        raise ValueError(f"Failed to decode token: {e}")

    try:
        token_object = cPickle.loads(decoded_token)
    except (cPickle.UnpicklingError, EOFError) as e:
        raise ValueError(f"Failed to unpickle token: {e}")

    if not isinstance(token_object, Token):
        raise ValueError("Decoded token is not of expected type")

    if not token_object.is_valid():
        raise ValueError("Token has expired")

    return token_object.data
```

